package owl.nh;
import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
final class SlayerPanel extends JFrame {
 private final Timer timer;
 SlayerPanel(CombatRuntime runtime,SlayerController fighter){super("Turbo Slayer");TurboBranding.apply(this);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JLabel selected=new JLabel("Selected: "+fighter.selected),progress=new JLabel("Ready");JTextArea status=new JTextArea(5,42);status.setEditable(false);status.setLineWrap(true);status.setWrapStyleWord(true);JPanel actions=new JPanel(new GridLayout(2,2,8,8));JButton pick=new JButton("Select NPC in game"),last=new JButton("Use last killed"),start=new JButton("Start"),stop=new JButton("Stop / F9");JSpinner kills=new JSpinner(new SpinnerNumberModel(1,1,10000,1));actions.add(pick);actions.add(last);actions.add(start);actions.add(stop);JComboBox<String> offensive=choices("None","Mystic will","Mystic lore","Mystic might","Augury","Sharp eye","Hawk eye","Eagle eye","Rigour","Burst of strength","Superhuman strength","Ultimate strength","Chivalry","Piety");JComboBox<String> defensive=choices("None","Protect from magic","Protect from missiles","Protect from melee");select(offensive,fighter.offensivePrayer);select(defensive,fighter.defensivePrayer);JPanel prayers=new JPanel(new GridLayout(2,2,8,4));prayers.add(new JLabel("Offensive prayer"));prayers.add(offensive);prayers.add(new JLabel("Defensive prayer"));prayers.add(defensive);JPanel top=new JPanel(new GridLayout(5,1,4,4));top.add(selected);JPanel count=new JPanel();count.add(new JLabel("Number to kill"));count.add(kills);top.add(count);top.add(prayers);top.add(progress);top.add(new JLabel("Uses your current gear/spell. Stand near the NPCs before Start."));root.add(top,BorderLayout.NORTH);root.add(actions,BorderLayout.CENTER);root.add(new JScrollPane(status),BorderLayout.SOUTH);setContentPane(root);setSize(640,480);setLocationByPlatform(true);
  pick.addActionListener(e->runtime.thread.invoke(fighter::pick));last.addActionListener(e->runtime.thread.invoke(()->{try{fighter.lastKilled();}catch(RuntimeException error){fighter.status=error.getMessage();}}));start.addActionListener(e->{int amount=(Integer)kills.getValue();net.runelite.api.Prayer attack=prayer(offensive),protection=prayer(defensive);runtime.thread.invoke(()->{try{fighter.offensivePrayer=attack;fighter.defensivePrayer=protection;fighter.start(amount);}catch(RuntimeException error){fighter.status=error.getMessage();}});});stop.addActionListener(e->runtime.thread.invoke(()->runtime.stop("Slayer Stop")));timer=new Timer(150,e->{selected.setText("Selected: "+fighter.selected);progress.setText(fighter.progress()+" | Name privacy: "+runtime.privacy.status);status.setText(fighter.status);});timer.start();addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){runtime.thread.invoke(()->runtime.stop("Slayer window closed"));dispose();}});
 }
 private static JComboBox<String> choices(String... values){return new JComboBox<>(values);}
 private static net.runelite.api.Prayer prayer(JComboBox<String> choice){String name=(String)choice.getSelectedItem();return "None".equals(name)?null:net.runelite.api.Prayer.valueOf(name.toUpperCase(java.util.Locale.ROOT).replace(' ','_'));}
 private static void select(JComboBox<String> choice,net.runelite.api.Prayer prayer){if(prayer!=null)for(int i=0;i<choice.getItemCount();i++)if(choice.getItemAt(i).replace(' ','_').equalsIgnoreCase(prayer.name()))choice.setSelectedIndex(i);}
 @Override public void dispose(){timer.stop();super.dispose();}
}
